function fnv1aHex(str){
  let h=0x811c9dc5;
  for(let i=0;i<str.length;i++) {
    h^=str.charCodeAt(i);
    h=Math.imul(h,0x01000193)>>>0;
  }
  return h.toString(16).padStart(8,"0");
}

function toAbs(input){
  if(typeof input!=="string") return null;
  if(/^(data:|blob:|mailto:|tel:|javascript:|#)/i.test(input)) return null;
  try {
    return new URL(input, SOURCE_ORIGIN + "/").href;
  } catch {
    return null;
  }
}

function shouldSkip(input){
  const abs=toAbs(input);
  return !!(abs && SKIP.some(s=>abs.startsWith(s)));
}

function bodyToText(body){
  try {
    if(body==null) return "";
    if(typeof body==="string") return body;
    if(body instanceof URLSearchParams) return body.toString();
    if(body instanceof FormData) return JSON.stringify(Array.from(body.entries()));
    if(typeof body==="object") return JSON.stringify(body);
    return String(body);
  } catch {
    return "";
  }
}

function keyFor(input, body){
  const abs=toAbs(input);
  if(!abs) return input;
  const u=new URL(abs);
  u.hash="";
  if(u.pathname.startsWith("/_framer/api/")) {
    const digest=fnv1aHex(u.pathname + (u.search || "") + bodyToText(body));
    u.search="?data="+digest;
  }
  return u.href;
}

function remap(input, body){
  try {
    const key=keyFor(input, body);
    const mapped=MAP[key];
    if(mapped) return new URL(mapped, SITE_ROOT).href;

    const abs=toAbs(input);
    if(abs) {
      const noQuery=new URL(abs);
      noQuery.search="";
      noQuery.hash="";
      const mappedNoQuery=MAP[noQuery.href];
      if(mappedNoQuery) return new URL(mappedNoQuery, SITE_ROOT).href;
    }
  } catch {}
  return input;
}

// Cheap structural guard: returns false when `s` can never match MAP, so callers
// can skip the expensive remap()/new URL() work. remap() only ever rewrites
// values that resolve to a source host; every MAP key carries one, and
// root-relative paths ("/x", "//host/x") resolve against the source origin.
// Anything else (class names, transforms, colors, foreign absolute URLs that
// aren't in MAP) is returned unchanged by remap() anyway, so skipping is safe.
const URL_ATTRS={src:1,href:1,data:1,poster:1,"data-poster":1};
function couldRemap(s){
  if(typeof s!=="string" || s.length===0) return false;
  if(s.charCodeAt(0)===47) return true; // '/' -> root-relative or protocol-relative '//'
  for(let i=0;i<REMAP_HOSTS.length;i++){
    if(s.indexOf(REMAP_HOSTS[i])!==-1) return true;
  }
  return false;
}

function rewriteSrcset(value){
  if(typeof value!=="string") return value;
  return value.split(",").map(part=>{
    const bits=part.trim().split(/\s+/);
    if(!bits[0]) return part;
    bits[0]=remap(bits[0]);
    return bits.join(" ");
  }).join(", ");
}

function rewriteMarkup(html){
  if(typeof html!=="string") return html;
  return html.replace(/https?:\/\/[^\s"'<>]+/g, m => {
    try {
      const key=keyFor(m);
      const mapped=MAP[key];
      if(mapped) return new URL(mapped, SITE_ROOT).href;

      const u=new URL(m);
      u.search="";
      u.hash="";
      const mappedNoQuery=MAP[u.href];
      return mappedNoQuery ? new URL(mappedNoQuery, SITE_ROOT).href : m;
    } catch {
      return m;
    }
  });
}

function normalizePath(path){
    let p=String(path || "/");
    if(!p.startsWith("/")) p="/"+p;
    if(p.length>1 && p.endsWith("/")) p=p.slice(0,-1);
    return p || "/";
}

function canonicalRuntimePath(path){
    const normalized=normalizePath(path);
    if(normalized==="/index.html") return "/";
    if(normalized.endsWith("/index.html")) {
        const trimmed=normalized.slice(0,-"/index.html".length);
        return normalizePath(trimmed || "/");
    }
    if(normalized.endsWith(".html")) {
        const trimmed=normalized.slice(0,-".html".length);
        return normalizePath(trimmed || "/");
    }
    return normalized;
}

function expectedRobots(path){
    return INDEXABLE_PATHS.has(canonicalRuntimePath(path)) ? "index" : "noindex";
}

function expectedCanonical(path){
    return new URL(canonicalRuntimePath(path), EXPORT_BASE + "/").href;
}

function locale404Target(path){
    const normalized=canonicalRuntimePath(path);
    if(KNOWN_PATHS.has(normalized)) return null;
    const parts=normalized.split("/").filter(Boolean);
    if(parts.length < 2) return null;
    const lastPart=parts[parts.length-1] || "";
    if(lastPart.includes(".")) return null;
    const locale=parts[0].toLowerCase();
    const target=LOCALE_404_TARGETS[locale];
    if(!target) return null;
    if(parts[1]==="404") return null;
    return target;
}

function maybeRedirectToLocale404(){
    const target=locale404Target(location.pathname);
    if(!target) return false;
    if(normalizePath(location.pathname)===normalizePath(target)) return false;
    if(location.pathname.startsWith(target + "/")) return false;
    location.replace(target + location.search + location.hash);
    return true;
}

function ensureMeta(name, content){
    const selector='meta[name="'+name+'"]';
    const tags=[...document.head.querySelectorAll(selector)];
    let tag=tags[0];
    if(!tag){
        tag=document.createElement("meta");
        tag.setAttribute("name", name);
        document.head.appendChild(tag);
    }
    for(let i=1;i<tags.length;i++) tags[i].remove();
    if(tag.getAttribute("content")!==content) tag.setAttribute("content", content);
}

function ensureCanonical(href){
    const tags=[...document.head.querySelectorAll('link[rel="canonical"]')];
    let tag=tags[0];
    if(!tag){
        tag=document.createElement("link");
        tag.setAttribute("rel","canonical");
        document.head.appendChild(tag);
    }
    for(let i=1;i<tags.length;i++) tags[i].remove();
    if(tag.getAttribute("href")!==href) tag.setAttribute("href", href);
}

function applySeoGuard(){
    if(!SEO_GUARD_ENABLED) return;
    if(!document.head) return;
    const path=normalizePath(location.pathname);
    const robots=expectedRobots(path);
    ensureMeta("robots", robots);
    ensureCanonical(expectedCanonical(path));
}

