if(window.fetch) {
  const origFetch=window.fetch.bind(window);
  window.fetch=(input, init={})=>{
    const raw=typeof input==="string" ? input : (input && input.url ? input.url : "");
    if(raw && shouldSkip(raw)) return Promise.resolve(new Response("", {status:204,statusText:"Skipped"}));
    const mapped=remap(raw, init && init.body);
    if(typeof input==="string") return origFetch(mapped, init);
    if(input instanceof Request) return origFetch(new Request(mapped, input), init);
    return origFetch(input, init);
  };
}

function patchProp(proto, prop){
  if(!proto) return;
  const d=Object.getOwnPropertyDescriptor(proto, prop);
  if(!d || !d.set) return;
  Object.defineProperty(proto, prop, {
    configurable:true,
    enumerable:d.enumerable,
    get(){ return d.get.call(this); },
    set(v){
      try {
        if(prop==="srcset") d.set.call(this, rewriteSrcset(v));
        else if(couldRemap(v)) d.set.call(this, remap(v));
        else d.set.call(this, v);
      } catch {
        d.set.call(this, v);
      }
    }
  });
}

